//! The release signature of the updater (E12, r-lokal-2; suite expectations
//! E12-a to E12-h of the review 2026-11-07). Every key is generated by the
//! test (`Ed25519KeyPair::generate_pkcs8`) and installed through the test port
//! of the release key; the project's key is never used and no server beyond
//! the loopback is asked.
use super::{
    parse_manifest, verify_manifest, ManifestEntry, MANIFEST_ASSET, MAX_MANIFEST_BYTES,
    MAX_SIGNATURE_BYTES, SIGNATURE_ASSET,
};
use crate::updater::download_bound::tests::http_fixture::{HttpFeed, Route};
use crate::updater::feed_trust::read_trust;
use crate::updater::feed_trust::tests::fixture::{
    manifest as manifest_bytes, sha256_hex, sign_with_another_key, AppData, ReleaseFolder, TestKey,
    VERSION,
};
use crate::updater::feed_trust::UnsignedConsent;
use crate::updater::staging::stage_from_feed;

fn consents() -> [(&'static str, UnsignedConsent); 2] {
    [
        ("without consent", UnsignedConsent::none()),
        ("with consent", UnsignedConsent::for_version(VERSION)),
    ]
}

/// A refusal: the error starts with `code`, whatever the consent, and no
/// payload, partial download or staging manifest is left in the app data.
fn assert_refused(app: &AppData, feed: &crate::updater::feed::Feed, code: &str, case: &str) {
    for (consent_case, consent) in consents() {
        let error = stage_from_feed(feed, VERSION, &consent)
            .err()
            .unwrap_or_else(|| panic!("{case} {consent_case}: the release was staged"));
        assert!(
            error.starts_with(code),
            "{case} {consent_case}: expected {code}, got {error}"
        );
        assert_eq!(
            app.staged_names(),
            Vec::<String>::new(),
            "{case} {consent_case}"
        );
    }
}

/// E12-a: a release with a valid signature is staged without consent, every
/// payload (including the launcher) bound to the manifest.
#[test]
fn lokal_task_signed_release_is_staged_without_consent() {
    let app = AppData::new();
    let key = TestKey::install();
    let release = ReleaseFolder::new(VERSION);
    release.sign(&key);
    let bundle = stage_from_feed(&release.feed(), VERSION, &UnsignedConsent::none())
        .unwrap_or_else(|error| panic!("a signed release: {error}"));
    assert_eq!(bundle.unsigned(), None);
    assert_eq!(bundle.version(), VERSION);
    assert_eq!(bundle.app().sha256(), release.payload("app").sha256());
    assert_eq!(
        bundle.helper().sha256(),
        release.payload("updater").sha256()
    );
    assert_eq!(bundle.cli().sha256(), release.payload("cli").sha256());
    assert_eq!(
        bundle
            .launcher()
            .map(|launcher| launcher.sha256().to_string()),
        Some(release.payload("launcher").sha256())
    );
    let loaded = crate::updater::load_staged_update()
        .expect("the staged update loads")
        .expect("a staged update exists");
    assert_eq!(loaded, bundle);
    crate::updater::discard_staged_update(&bundle).expect("the staged update is discarded");
    assert_eq!(app.staged_names(), Vec::<String>::new());
}

/// E12-b: a changed byte, another key, a changed signature: never staged,
/// with or without consent.
#[test]
fn lokal_task_changed_manifest_or_signature_is_never_staged() {
    let app = AppData::new();
    let key = TestKey::install();
    let release = ReleaseFolder::new(VERSION);
    release.sign(&key);
    let manifest = release.read(MANIFEST_ASSET);
    let signature = release.read(SIGNATURE_ASSET);

    let mut changed = manifest.clone();
    let last = changed.len() - 5;
    changed[last] ^= 0x01;
    release.write(MANIFEST_ASSET, &changed);
    assert_refused(
        &app,
        &release.feed(),
        "update_signature_invalid",
        "manifest byte",
    );

    release.write(MANIFEST_ASSET, &manifest);
    let mut forged = signature.clone();
    forged[0] = if forged[0] == b'0' { b'1' } else { b'0' };
    release.write(SIGNATURE_ASSET, &forged);
    assert_refused(
        &app,
        &release.feed(),
        "update_signature_invalid",
        "signature digit",
    );

    release.write(SIGNATURE_ASSET, &sign_with_another_key(&manifest));
    assert_refused(
        &app,
        &release.feed(),
        "update_signature_invalid",
        "another key",
    );

    // Control: the untouched pair is accepted again.
    release.write(SIGNATURE_ASSET, &signature);
    assert!(stage_from_feed(&release.feed(), VERSION, &UnsignedConsent::none()).is_ok());
}

/// E12-c, E12-d, E12-e: the signed version must be the feed's, both files
/// must be there, and the sidecar must name the signed hash.
#[test]
fn lokal_task_version_missing_file_and_sidecar_mismatch_are_refused() {
    let app = AppData::new();
    let key = TestKey::install();
    let release = ReleaseFolder::new(VERSION);

    release.sign_as(&key, "999.0.1");
    assert_refused(
        &app,
        &release.feed(),
        "update_signature_version",
        "other version",
    );

    release.sign(&key);
    let signature = release.read(SIGNATURE_ASSET);
    release.remove(SIGNATURE_ASSET);
    assert_refused(
        &app,
        &release.feed(),
        "update_signature_missing",
        "manifest only",
    );
    release.write(SIGNATURE_ASSET, &signature);
    release.remove(MANIFEST_ASSET);
    assert_refused(
        &app,
        &release.feed(),
        "update_signature_missing",
        "signature only",
    );

    release.sign(&key);
    let app_payload = release.payload("app");
    release.write(
        app_payload.hash_name,
        format!("{}  {}\n", sha256_hex(b"another payload"), app_payload.name).as_bytes(),
    );
    assert_refused(
        &app,
        &release.feed(),
        "update_signature_mismatch",
        "sidecar hash",
    );
}

/// E12-f (folder): one byte more or less than the signed size, and an asset
/// the manifest does not list, are refused before a copy is staged.
#[test]
fn lokal_task_folder_payload_must_have_the_signed_size_and_be_listed() {
    let app = AppData::new();
    let key = TestKey::install();
    let release = ReleaseFolder::new(VERSION);
    release.sign(&key);
    let app_payload = release.payload("app");

    let mut longer = app_payload.bytes.clone();
    longer.push(0);
    release.write(app_payload.name, &longer);
    assert_refused(
        &app,
        &release.feed(),
        "update_signature_mismatch",
        "one byte more",
    );

    release.write(
        app_payload.name,
        &app_payload.bytes[..app_payload.bytes.len() - 1],
    );
    assert_refused(
        &app,
        &release.feed(),
        "update_signature_mismatch",
        "one byte less",
    );

    // The launcher exists in the folder but the signed manifest omits it.
    release.write(app_payload.name, &app_payload.bytes);
    let listed: Vec<(&str, &[u8])> = release
        .payloads()
        .iter()
        .filter(|payload| payload.role != "launcher")
        .map(|payload| (payload.name, payload.bytes.as_slice()))
        .collect();
    let manifest = manifest_bytes(VERSION, &listed);
    release.write(SIGNATURE_ASSET, &key.sign(&manifest));
    release.write(MANIFEST_ASSET, &manifest);
    for (case, consent) in consents() {
        let error = stage_from_feed(&release.feed(), VERSION, &consent)
            .err()
            .unwrap_or_else(|| panic!("{case}: an unlisted launcher was staged"));
        assert!(error.contains("Starter"), "{case}: {error}");
        assert_eq!(app.staged_names(), Vec::<String>::new(), "{case}");
    }
}

/// E12-f (HTTP): the signed release over loopback HTTP is staged; one byte
/// more than the signed length stops the download and removes the partial
/// file.
#[test]
fn lokal_task_http_payload_beyond_the_signed_length_is_cut_off() {
    let app = AppData::new();
    let key = TestKey::install();
    let release = ReleaseFolder::new(VERSION);
    release.sign(&key);
    let server = HttpFeed::start();
    server.serve_folder(&release);

    let bundle = stage_from_feed(&server.feed(), VERSION, &UnsignedConsent::none())
        .unwrap_or_else(|error| panic!("the signed release over HTTP: {error}"));
    assert_eq!(bundle.unsigned(), None);
    let requests = server.requests();
    assert!(
        requests.contains(&MANIFEST_ASSET.to_string()),
        "{requests:?}"
    );
    assert!(
        requests.contains(&SIGNATURE_ASSET.to_string()),
        "{requests:?}"
    );
    crate::updater::discard_staged_update(&bundle).expect("the staged update is discarded");

    let mut longer = release.payload("app").bytes.clone();
    longer.push(0);
    for name in crate::updater::os::app_payload_spec().http_names {
        server.serve(name, Route::plain(longer.clone()));
    }
    for (case, consent) in consents() {
        let error = stage_from_feed(&server.feed(), VERSION, &consent)
            .err()
            .unwrap_or_else(|| panic!("{case}: a payload beyond its signed length was staged"));
        assert!(
            error.contains("more bytes than its announced or signed length"),
            "{case}: {error}"
        );
        assert_eq!(app.staged_names(), Vec::<String>::new(), "{case}");
    }
}

/// E12-g: the manifest is read strictly, so two readers never disagree about
/// one signed file; a name with spaces is a name.
#[test]
fn lokal_task_manifest_parser_accepts_only_the_canonical_form() {
    let assets: [(&str, &[u8]); 2] = [
        ("Smart Explorer Setup 1.2.3.exe", b"abcde"),
        ("version.txt", b"1.2.3\n"),
    ];
    let valid = String::from_utf8(manifest_bytes("1.2.3", &assets)).expect("UTF-8");
    let lines: Vec<&str> = valid.trim_end_matches('\n').split('\n').collect();
    assert_eq!(lines.len(), 4);
    let parsed = parse_manifest(valid.as_bytes()).expect("the canonical manifest");
    assert_eq!(
        parsed.entry("Smart Explorer Setup 1.2.3.exe"),
        Some(&ManifestEntry {
            sha256: sha256_hex(b"abcde"),
            size: 5
        })
    );
    assert_eq!(parsed.entry("version.txt").map(|entry| entry.size), Some(6));
    assert!(parsed.entry("smart explorer setup 1.2.3.exe").is_none());

    let (first, second) = (lines[2], lines[3]);
    let head = format!("{}\n{}\n", lines[0], lines[1]);
    let first_hash = first.split(' ').next().expect("a hash");
    let cases: Vec<(&str, Vec<u8>)> = vec![
        ("CRLF", valid.replace('\n', "\r\n").into_bytes()),
        (
            "empty line",
            format!("{head}{first}\n\n{second}\n").into_bytes(),
        ),
        (
            "uppercase hex",
            valid
                .replacen(first_hash, &first_hash.to_uppercase(), 1)
                .into_bytes(),
        ),
        (
            "leading zero",
            valid.replacen(" 5 ", " 05 ", 1).into_bytes(),
        ),
        (
            "size not a number",
            valid.replacen(" 5 ", " x ", 1).into_bytes(),
        ),
        (
            "duplicate name",
            format!("{head}{first}\n{first}\n").into_bytes(),
        ),
        (
            "descending names",
            format!("{head}{second}\n{first}\n").into_bytes(),
        ),
        (
            "no final LF",
            valid.trim_end_matches('\n').as_bytes().to_vec(),
        ),
        (
            "other header",
            valid.replacen("manifest 1", "manifest 2", 1).into_bytes(),
        ),
        (
            "no version line",
            format!("{}\n{first}\n{second}\n", lines[0]).into_bytes(),
        ),
        (
            "version with a space",
            valid
                .replacen("version 1.2.3", "version 1.2 3", 1)
                .into_bytes(),
        ),
        (
            "trailing space in a name",
            format!("{head}{first}\n{second} \n").into_bytes(),
        ),
        (
            "leading space in a name",
            format!(
                "{head}{first}\n{}\n",
                second.replacen(" version.txt", "  version.txt", 1)
            )
            .into_bytes(),
        ),
        (
            "control character",
            format!("{head}{first}\n{second}\u{7}\n").into_bytes(),
        ),
        (
            "short hash",
            valid.replacen(first_hash, &first_hash[1..], 1).into_bytes(),
        ),
        ("no assets", head.clone().into_bytes()),
        ("not UTF-8", vec![0xff, 0xfe, b'\n']),
        ("empty", Vec::new()),
    ];
    for (case, bytes) in cases {
        let error = parse_manifest(&bytes)
            .err()
            .unwrap_or_else(|| panic!("{case}: accepted"));
        assert!(
            error.starts_with("update_manifest_malformed"),
            "{case}: {error}"
        );
    }
}

/// E12-h and the signature file: sizes and encodings at their limits, and the
/// binding of a sidecar to the signed hash.
#[test]
fn lokal_task_manifest_and_signature_limits_and_binding() {
    let _app = AppData::new();
    let key = TestKey::install();
    let release = ReleaseFolder::new(VERSION);
    release.sign(&key);
    let feed = release.feed();
    let manifest = release.read(MANIFEST_ASSET);
    let signature = release.read(SIGNATURE_ASSET);
    let error_of = |case: &str| {
        read_trust(&feed, VERSION)
            .err()
            .unwrap_or_else(|| panic!("{case}: accepted"))
    };

    assert!(read_trust(&feed, VERSION).is_ok());

    release.write(MANIFEST_ASSET, &vec![b'a'; MAX_MANIFEST_BYTES as usize + 1]);
    let error = error_of("manifest over the limit");
    assert!(error.starts_with("update_signature_malformed"), "{error}");
    // Exactly at the limit it is read and then fails the signature.
    release.write(MANIFEST_ASSET, &vec![b'a'; MAX_MANIFEST_BYTES as usize]);
    let error = error_of("manifest at the limit");
    assert!(error.starts_with("update_signature_invalid"), "{error}");

    release.write(MANIFEST_ASSET, &manifest);
    release.write(
        SIGNATURE_ASSET,
        &vec![b'0'; MAX_SIGNATURE_BYTES as usize + 1],
    );
    let error = error_of("signature over the limit");
    assert!(error.starts_with("update_signature_malformed"), "{error}");
    for (case, bytes) in [
        ("signature one digit short", signature[..127].to_vec()),
        (
            "signature not hex",
            [vec![b'g'; 128], b"\n".to_vec()].concat(),
        ),
        ("signature empty", Vec::new()),
    ] {
        release.write(SIGNATURE_ASSET, &bytes);
        let error = error_of(case);
        assert!(
            error.starts_with("update_signature_malformed"),
            "{case}: {error}"
        );
    }
    // The signature may omit its final LF.
    release.write(
        SIGNATURE_ASSET,
        signature.strip_suffix(b"\n").expect("a final LF"),
    );
    assert!(read_trust(&feed, VERSION).is_ok());

    // The sidecar is bound to the signed hash (case-insensitive); an asset the
    // release does not contain is not bound.
    let verified = verify_manifest(&manifest, &signature, VERSION).expect("the signed manifest");
    let app_payload = release.payload("app");
    let hash = app_payload.sha256();
    assert_eq!(
        verified.bind(app_payload.name, &hash.to_uppercase()),
        Ok(Some(app_payload.bytes.len() as u64))
    );
    assert_eq!(verified.bind("not-in-the-release", &hash), Ok(None));
    let error = verified
        .bind(app_payload.name, &sha256_hex(b"other"))
        .expect_err("a sidecar that names another hash");
    assert!(error.starts_with("update_signature_mismatch"), "{error}");
}
